<script setup>
import {onMounted,ref,computed} from 'vue'
import CodeEditor from './CodeEditor.vue'
import PaymentFrame from '../../../shared/PaymentFrame.vue'
import {paymentProviders,validatePayments} from '../../../shared/payments.js'
const props=defineProps({apiWrite:Function})
const form=ref(null),originText=ref(''),busy=ref(false),error=ref(''),notice=ref(''),preview=ref(null)
const provider=computed(()=>paymentProviders.find(p=>p.id===form.value?.provider))
async function load(){busy.value=true;error.value='';preview.value=null;try{form.value=await props.apiWrite('/api/admin/payments','GET');originText.value=form.value.origins.join('\n')}catch(e){error.value=e.message}finally{busy.value=false}}
function selectProvider(){preview.value=null;originText.value=provider.value.origins.join('\n');notice.value='Проверьте источники, ссылку и код нового сервиса перед сохранением.'}
function value(){return {...form.value,origins:originText.value.split(/\s+/).filter(Boolean)}}
async function save(){if(busy.value)return;const config=value(),invalid=validatePayments(config,[location.origin]);if(invalid){error.value=invalid;return}busy.value=true;error.value='';notice.value='';preview.value=null;try{form.value=await props.apiWrite('/api/admin/payments','PUT',config);originText.value=form.value.origins.join('\n');notice.value='Настройки оплаты сохранены.'}catch(e){error.value=e.message}finally{busy.value=false}}
function showPreview(){const c=value(),invalid=validatePayments({...c,enabled:false},[location.origin]);if(invalid){error.value=invalid;return}error.value='';preview.value=c}
onMounted(load)
</script>
<template>
<div class="payments-workspace"><div class="page-title"><div><span class="eyebrow">МАГАЗИН</span><h1>Оплата</h1><p>Подключите готовую платёжную страницу или публичный код виджета.</p></div><button class="row-btn" :disabled="busy" @click="load">Обновить</button></div>
<p v-if="error" class="alert" role="alert">{{error}}</p><p v-if="notice" class="payment-notice" role="status">{{notice}}</p>
<form v-if="form" @submit.prevent="save"><fieldset :disabled="busy"><section class="panel payment-settings"><h2>Подключение</h2><label class="payment-toggle"><input v-model="form.enabled" type="checkbox"> Предлагать оплату после оформления заказа</label><div class="payment-grid"><label>Платёжный сервис<select aria-label="Платёжный сервис" v-model="form.provider" @change="selectProvider"><option v-for="p in paymentProviders" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Способ подключения<select aria-label="Способ подключения" v-model="form.mode" @change="preview=null"><option value="link">Платёжная ссылка</option><option value="widget">HTML / JavaScript / iframe</option></select></label></div><p>{{provider.hint}} <a v-if="provider.url" :href="provider.url" target="_blank" rel="noopener noreferrer">Официальная инструкция ↗</a></p><label>Заголовок для покупателя<input v-model="form.title" maxlength="150" required></label><label>Инструкция покупателю<textarea v-model="form.instructions" maxlength="3000" rows="3"></textarea></label><label>{{form.mode==='widget'?'Резервная платёжная ссылка (необязательно)':'Платёжная ссылка'}}<input v-model="form.link" type="url" maxlength="2000" placeholder="https://…"></label><label>Разрешённые HTTPS-источники, по одному на строке<textarea v-model="originText" rows="5" spellcheck="false" placeholder="https://auth.robokassa.ru"></textarea></label><p>Укажите точные источники скриптов, iframe, запросов и форм из инструкции сервиса. Без путей и звёздочек. Для PayKeeper нужен ваш персональный домен. Домены 3-D Secure добавляйте по документации сервиса. Скрипты запускаются только при открытии оплаты покупателем.</p></section>
<section v-if="form.mode==='widget'" class="panel payment-settings"><h2>Код, выданный платёжной системой</h2><p>Вставьте публичный HTML-код целиком, включая &lt;script&gt;, стили или iframe. Секретные ключи, пароли и API Secret сюда вставлять нельзя: этот код увидит покупатель.</p><CodeEditor v-model="form.code" language="HTML / JavaScript" :disabled="busy" @save="save"/><p>Внутри формы доступен объект <code>window.NOVA_PAYMENT</code>: <code>order_number</code>, <code>amount</code> (рубли строкой), <code>amount_cents</code>, <code>currency</code>. Используйте его только если инструкция виджета разрешает динамические параметры. Готовые подписи и фиксированные ссылки не пересчитываются для нового заказа.</p><p>Некоторые виджеты требуют отдельного домена или серверной подписи и не работают в изоляции. Для них используйте платёжную ссылку или отдельный серверный адаптер.</p><button type="button" class="row-btn" @click="showPreview">Открыть предпросмотр кода</button><p>Предпросмотр выполняет вставленный код с примером заказа N000001 на 100 ₽. Используйте тестовый код сервиса; предпросмотр сам не переключает платёжную систему в тестовый режим.</p><div v-if="preview"><button type="button" class="row-btn" @click="preview=null">Закрыть предпросмотр</button><PaymentFrame :config="preview" :order="{number:'N000001',total_cents:10000}"/></div></section>
<section class="panel payment-settings"><h2>Подтверждение поступлений</h2><p>В этом режиме оплата проверяется вручную в кабинете платёжного сервиса. В разделе «Заказы» укажите номер операции и подтвердите поступление. Возврат также сначала выполняется у платёжного сервиса, затем отмечается в заказе.</p><p>Сообщение виджета, нажатие кнопки и возврат с платёжной страницы не меняют статус заказа на «Оплачен». Автоматические уведомления, серверные подписи и фискализация требуют отдельной интеграции с API выбранного сервиса. Параметры чека настраиваются в самом сервисе.</p><button class="primary-btn">{{busy?'Сохранение…':'Сохранить настройки'}}</button></section></fieldset></form>
<section class="panel payment-settings"><h2>Сервисы и документация</h2><div class="payment-providers"><article v-for="p in paymentProviders.filter(p=>p.url)" :key="p.id"><h3>{{p.name}}</h3><p>{{p.hint}}</p><a :href="p.url" target="_blank" rel="noopener noreferrer">Документация ↗</a></article></div></section>
</div>
</template>
<style scoped>
.payment-settings{padding:24px;margin-bottom:20px;display:grid;gap:16px;min-width:0}.payment-settings h2,.payment-settings p{margin:0}.payment-settings p{font-size:13px;line-height:1.7;color:#567166}.payment-settings label{display:grid;gap:8px;font-size:13px;font-weight:600}.payment-settings input,.payment-settings select,.payment-settings textarea{font:inherit;padding:12px;border:1px solid #d4dfd9;border-radius:8px;width:100%;box-sizing:border-box;background:#fff;color:#19372b}.payment-toggle{display:flex!important;align-items:center}.payment-toggle input{width:auto}.payment-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.payment-settings a{color:#257153}.payment-settings code{overflow-wrap:anywhere}.payments-workspace fieldset{border:0;padding:0;margin:0;min-width:0}.payment-notice{padding:15px;background:#e7f4eb;color:#24633c;border-radius:8px}.payment-providers{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px}.payment-providers article{border:1px solid #dce6e0;border-radius:8px;padding:18px}.payment-providers h3{margin:0 0 10px;font-size:16px}.payment-providers a{display:block;margin-top:12px;font-size:13px}@media(max-width:650px){.payment-grid{grid-template-columns:1fr}.payment-settings{padding:16px}}
</style>
